        // prøv alle mulige posisjoner for dronningen i den nåværende raden
        for (int i = 1; i <= n; i++)
        {
            // sjekk om dronningen kan plasseres på den nåværende posisjonen
            if (canPlace(k, i))
            {
                // plasser dronningen på den nåværende posisjonen
                arr[k] = i;

                // hvis alle dronninger er plassert, vis løsningen
                if (k == n)
                {
                    display(n);
                }
                else
                {
                    // rekursivt prøv å plassere gjenværende dronninger
                    nQueens(k + 1, n);
                }
            }
        }
    }

    // hjelpefunksjon for å sjekke om dronningen kan plasseres på den nåværende posisjonen
    static bool canPlace(int k, int i)
    {
        for (int j = 1; j <= k - 1; j++)
        {
            // sjekk om dronningen allerede er plassert i samme kolonne eller diagonal
            if (arr[j] == i || (Math.Abs(arr[j] - i) == Math.Abs(j - k)))
            {
                return false;
            }
        }
        return true;
    }

    // funksjon for å vise løsningen
    static void display(int n)
    {
        breakLine();
